    adcs_status_t status = ADCS_OK;
    double norm;
    adcs_vec3_t sum_axes = {0.0, 0.0, 0.0};
    size_t i;

    if ((axes == NULL) || (wheel_torque_nm == NULL) || (spacecraft_residual_nm == NULL)) {
        return ADCS_E_NULL;
    }

    if (!isfinite(amplitude_nm)) {
        return ADCS_E_RANGE;
    }

    for (i = 0; i < 4; i++) {
        if (!adcs_is_finite_vec3(&axes[i])) {
            return ADCS_E_RANGE;
        }
        norm = adcs_vec3_norm(&axes[i]);
        if (fabs(norm - 1.0) > ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }
        sum_axes = adcs_vec3_add(&sum_axes, &axes[i]);
    }

    for (i = 0; i < 4; i++) {
        wheel_torque_nm[i] = amplitude_nm;
    }

    *spacecraft_residual_nm = adcs_vec3_scale(&sum_axes, -amplitude_nm);

    return ADCS_OK;
}

