    if ((axes == NULL) || (wheel_torque_nm == NULL) || (spacecraft_residual_nm == NULL)) {
        for (int i = 0; i < 4; ++i) {
            wheel_torque_nm[i] = 0.0;
        }
        spacecraft_residual_nm->x = 0.0;
        spacecraft_residual_nm->y = 0.0;
        spacecraft_residual_nm->z = 0.0;
        return ADCS_E_NULL;
    }

    if (!isfinite(amplitude_nm)) {
        for (int i = 0; i < 4; ++i) {
            wheel_torque_nm[i] = 0.0;
        }
        spacecraft_residual_nm->x = 0.0;
        spacecraft_residual_nm->y = 0.0;
        spacecraft_residual_nm->z = 0.0;
        return ADCS_E_RANGE;
    }

    double sum_x = 0.0;
    double sum_y = 0.0;
    double sum_z = 0.0;
    const double eps_norm = 1.0e-12;

    for (int i = 0; i < 4; ++i) {
        double n_sq = axes[i].x * axes[i].x + axes[i].y * axes[i].y + axes[i].z * axes[i].z;
        double norm = sqrt(n_sq);
        if (fabs(norm - 1.0) > eps_norm) {
            for (int j = 0; j < 4; ++j) {
                wheel_torque_nm[j] = 0.0;
            }
            spacecraft_residual_nm->x = 0.0;
            spacecraft_residual_nm->y = 0.0;
            spacecraft_residual_nm->z = 0.0;
            return ADCS_E_RANGE;
        }
        sum_x += axes[i].x;
        sum_y += axes[i].y;
        sum_z += axes[i].z;
    }

    for (int i = 0; i < 4; ++i) {
        wheel_torque_nm[i] = amplitude_nm;
    }

    spacecraft_residual_nm->x = -amplitude_nm * sum_x;
    spacecraft_residual_nm->y = -amplitude_nm * sum_y;
    spacecraft_residual_nm->z = -amplitude_nm * sum_z;

    return ADCS_OK;
}

